import { DropPlatform, createPlatform, PlatformConfig } from './platform';
import { RouterService } from './router';
import { CaddyServer } from '../managers/router';
import { createApiServer } from '../api';
import { eventBus } from './event-bus';
import { getStateManager } from '../managers/app/state-manager';
import { getAppConfigService } from '../managers/app/app-config';
import { getSuspensionStore } from '../managers/suspension';
import * as authModule from '../api/middleware/auth';

async function waitFor(predicate: () => boolean, timeoutMs = 8000, intervalMs = 25): Promise<void> {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (predicate()) return;
    await new Promise((r) => setTimeout(r, intervalMs));
  }
  throw new Error('waitFor: condition not met within timeout');
}

async function eventually(check: () => Promise<boolean>, timeoutMs = 8000): Promise<void> {
  const started = Date.now();
  while (Date.now() - started < timeoutMs) {
    if (await check()) return;
    await new Promise((r) => setTimeout(r, 25));
  }
  throw new Error('eventually: condition not met within timeout');
}

interface PlatformInternals {
  router: RouterService;
  appsInProgress: Set<string>;
  handleConfigureRoute: (name: string, port: number, opts?: { skipCaddyReload?: boolean }) => Promise<void>;
  reconfigureRoute: (name: string) => Promise<void>;
  logger: { warn: (...args: unknown[]) => void };
}

describe('app suspension (platform, Item 3: serving)', () => {
  let tempDir: string;
  let webappsDir: string;
  let caddyfile: string;
  let suspensionsFile: string;
  let platform: DropPlatform | null = null;
  const internals = (): PlatformInternals => platform as unknown as PlatformInternals;

  beforeEach(async () => {
    tempDir = await fs.mkdtemp(path.join(os.tmpdir(), 'drop-suspension-serving-'));
    webappsDir = path.join(tempDir, 'webapps');
    caddyfile = path.join(tempDir, 'Caddyfile');
    suspensionsFile = path.join(tempDir, 'data', 'drop-svc', 'suspensions.json');
    fakeRuntime.reset();
  });

  afterEach(async () => {
    if (platform && platform.isActive()) await platform.stop();
    platform = null;
    await fs.rm(tempDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 100 });
    jest.restoreAllMocks();
  });

  function makePlatform(overrides?: Partial<PlatformConfig>): DropPlatform {
    return createPlatform({
      dropRoot: tempDir,
      appsDirectory: webappsDir,
      logLevel: 'error',
      autoBuild: true,
      autoStart: true,
      enableApi: false,
      enableHttps: false,
      caddyfilePath: caddyfile,
      ...overrides,
    });
  }

  async function createStaticApp(name: string): Promise<string> {
    const appPath = path.join(webappsDir, name);
    await fs.mkdir(appPath, { recursive: true });
    await fs.writeFile(path.join(appPath, 'index.html'), `<h1>${name}</h1>`);
    return appPath;
  }

  /**
   * Deploy a static app and wait until it runs and is settled, then route it. The
   * fake runtime publishes no `app:started` (PM2's process manager does, and the
   * platform routes on it), so the route is written the way that handler does.
   */
  async function deploy(name: string): Promise<string> {
    const appPath = await createStaticApp(name);
    eventBus.publish('app:detected', { name, path: appPath, type: undefined });
    await waitFor(
      () => getStateManager().getApp(name)?.status === 'running' && !internals().appsInProgress.has(name)
    );
    await internals().handleConfigureRoute(name, getStateManager().getApp(name)!.port!);
    await waitFor(() => routed(name));
    return appPath;
  }

  /** Whether the router holds a route OWNED by the app (route keys are `<app>/<host>`). */
  const routed = (name: string): boolean => internals().router.getRoutes().some((r) => r.owner === name);

  const readCaddyfile = (): Promise<string> => fs.readFile(caddyfile, 'utf-8');

  /** Write the suspension file as the store would (records carry their app name). */
  async function writeRecords(names: string[], keyless = false): Promise<void> {
    const file: Record<string, unknown> = {};
    for (const name of names) {
      file[name.toLowerCase()] = { at: '2026-01-01T00:00:00.000Z', by: 'admin-1', ...(keyless ? {} : { app: name }) };
    }
    await fs.mkdir(path.dirname(suspensionsFile), { recursive: true });
    await fs.writeFile(suspensionsFile, JSON.stringify(file));
  }

  /**
   * Stub Caddy at the class and record what the runtime holds at the moment it is
   * started (ONE entry per start). Ready is forced true so the start is reached.
   */
  function watchCaddyStart(): string[][] {
    const heldAtStart: string[][] = [];
    jest.spyOn(CaddyServer.prototype, 'ensureReady').mockResolvedValue(true);
    jest.spyOn(CaddyServer.prototype, 'stop').mockResolvedValue(undefined);
    jest.spyOn(CaddyServer.prototype, 'start').mockImplementation(async () => {
      heldAtStart.push(fakeRuntime.runningNames().sort());
    });
    return heldAtStart;
  }

  /**
   * Wrap the boot enforcement step of `p` and capture the Caddyfile on either side
   * of it. (Startup itself writes the managed Caddyfile, and the router rewrites it
   * on a route change, so "unchanged" is a claim about THIS step, not about boot.)
   */
  function watchEnforcement(p: DropPlatform): { before?: string; after?: string } {
    const seen: { before?: string; after?: string } = {};
    const target = p as unknown as { enforceSuspensionsAtBoot: () => Promise<void> };
    const real = target.enforceSuspensionsAtBoot.bind(p);
    jest.spyOn(target, 'enforceSuspensionsAtBoot').mockImplementation(async () => {
      seen.before = await readCaddyfile();
      await real();
      seen.after = await readCaddyfile();
    });
    return seen;
  }

  /**
   * The first platform's life: two apps, `site` and `blog`, deployed and routed.
   * Then it stops, leaving what PM2 would still have up. Returns the Caddyfile
   * as the stopped platform left it.
   */
  async function deployTwoAndStop(): Promise<string> {
    platform = makePlatform();
    await platform.start();
    await deploy('site');
    await deploy('blog');
    await eventually(async () => {
      const text = await readCaddyfile().catch(() => '');
      return text.includes('site.localhost') && text.includes('blog.localhost');
    });
    await platform.stop();
    platform = null;
    const text = await readCaddyfile();
    expect(text).toContain('site.localhost');
    expect(fakeRuntime.runningNames().sort()).toEqual(['blog', 'site']);
    return text;
  }

  describe('no route for a refused app', () => {
    it('handleConfigureRoute writes no route and persists nothing for an app a record holds', async () => {
      platform = makePlatform();
      await platform.start();
      await deploy('site');
      const port = getStateManager().getApp('site')!.port!;
      const add = jest.spyOn(internals().router, 'addRoute');

      // The control: an unsuspended app is routed.
      await internals().handleConfigureRoute('site', port);
      expect(add).toHaveBeenCalledTimes(1);

      await internals().router.removeRoutesForApp('site');
      add.mockClear();
      // The record only: nothing is taken down, so only the route writer can keep it unrouted.
      await getSuspensionStore().suspend('site', 'admin-1');
      const configBefore = JSON.stringify(getAppConfigService().getConfig('site'));

      await internals().handleConfigureRoute('site', port);

      expect(add).not.toHaveBeenCalled();
      expect(routed('site')).toBe(false);
      expect(JSON.stringify(getAppConfigService().getConfig('site'))).toBe(configBefore);
    }, 30000);

    it('a group child on a suspended container gets none either, and a sibling no record holds still does', async () => {
      platform = makePlatform();
      await platform.start();
      const frontend = await deploy('ezsign-frontend');
      const api = await deploy('ezsign-api');
      await fs.writeFile(path.join(frontend, 'drop.yaml'), 'name: ezsign-frontend\nroute:\n  path: /\n');
      await fs.writeFile(path.join(api, 'drop.yaml'), 'name: ezsign-api\nroute:\n  path: /api\n');
      await getAppConfigService().updateConfig('ezsign-frontend', { group: 'ezsign' });
      await getAppConfigService().updateConfig('ezsign-api', { group: 'ezsign' });
      const add = jest.spyOn(internals().router, 'addRoute');
      const portOf = (n: string): number => getStateManager().getApp(n)!.port!;

      await internals().handleConfigureRoute('ezsign-frontend', portOf('ezsign-frontend'));
      expect(add.mock.calls.map((c) => (c[0] as { hostname?: string }).hostname)).toEqual(['ezsign.localhost']);

      await internals().router.removeRoutesForApp('ezsign-frontend');
      add.mockClear();
      await getSuspensionStore().suspend('ezsign-frontend', 'admin-1');
      await internals().handleConfigureRoute('ezsign-frontend', portOf('ezsign-frontend'));
      expect(add).not.toHaveBeenCalled();
      expect(routed('ezsign-frontend')).toBe(false);

      await internals().handleConfigureRoute('ezsign-api', portOf('ezsign-api'));
      expect(add).toHaveBeenCalledTimes(1);
      expect((add.mock.calls[0][0] as { owner?: string; hostname?: string }).hostname).toBe('ezsign.localhost');
    }, 30000);

    it('reconfigureRoute withdraws the routes of a suspended app instead of rewriting them', async () => {
      platform = makePlatform();
      await platform.start();
      await deploy('site');
      expect(routed('site')).toBe(true);
      await getSuspensionStore().suspend('site', 'admin-1');
      const add = jest.spyOn(internals().router, 'addRoute');

      await internals().reconfigureRoute('site');

      expect(routed('site')).toBe(false);
      expect(add).not.toHaveBeenCalled();
      expect(internals().appsInProgress.has('site')).toBe(false);
    }, 30000);

    it('an unreadable store withdraws nothing and refuses to write nothing: the route is kept', async () => {
      platform = makePlatform();
      await platform.start();
      await deploy('site');
      jest.spyOn(console, 'error').mockImplementation();
      await fs.writeFile(suspensionsFile, '{ broken');
      await getSuspensionStore().load();
      expect(getSuspensionStore().isCorrupt()).toBe(true);
      const remove = jest.spyOn(internals().router, 'removeRoutesForApp');
      const add = jest.spyOn(internals().router, 'addRoute');

      await internals().reconfigureRoute('site');

      expect(remove).not.toHaveBeenCalled();
      expect(add).toHaveBeenCalledTimes(1);
      expect(routed('site')).toBe(true);
    }, 30000);
  });

  describe('RouterService on an unseeded router', () => {
    it('removing the routes of an app it never held rewrites no Caddyfile (the boot truncation trap)', async () => {
      const file = path.join(tempDir, 'Caddyfile.unseeded');
      const original = '# written by an earlier platform\nstale.localhost {\n  reverse_proxy localhost:4100\n}\n';
      await fs.writeFile(file, original);
      const router = new RouterService({
        caddy: { caddyfilePath: file, enableAdminApi: false, autoReload: true },
      });
      const mtime = (await fs.stat(file)).mtimeMs;

      await router.removeRoutesForApp('site');
      await router.removeRoutesForApp('site');
      await new Promise((r) => setTimeout(r, 700));

      expect(await fs.readFile(file, 'utf-8')).toBe(original);
      expect((await fs.stat(file)).mtimeMs).toBe(mtime);
      router.stop();
    });
  });

  describe.each([['off' as const], ['on' as const]])('boot enforcement with DROP_BOOT_RECONCILE=%s', (mode) => {
    it('deletes a live suspended instance (state-backed) before Caddy starts, logs it, and leaves the Caddyfile alone', async () => {
      await deployTwoAndStop();
      await writeRecords(['site']);
      const heldAtStart = watchCaddyStart();
      platform = makePlatform({ bootReconcileMode: mode });
      const seen = watchEnforcement(platform);
      const warn = jest.spyOn(internals().logger, 'warn');
      const remove = jest.spyOn(RouterService.prototype, 'removeRoutesForApp');
      const add = jest.spyOn(RouterService.prototype, 'addRoute');

      await platform.start();

      // Caddy started once, and by then the suspended instance was gone and the other still up.
      expect(heldAtStart).toEqual([['blog']]);
      expect(fakeRuntime.runningNames()).toEqual(['blog']);
      const site = getStateManager().getApp('site');
      expect(site?.status).toBe('stopped');
      expect(site?.error).toBe('Suspended by admin');
      expect(warn.mock.calls.some((c) => String(c[0]).includes("'site'") && String(c[0]).includes('taken down'))).toBe(true);

      // The unseeded router had nothing to remove, so the step rewrote no Caddyfile and routed nothing.
      expect(remove.mock.results.every((r) => r.type === 'return')).toBe(true);
      expect(seen.before).toBeDefined();
      expect(seen.after).toBe(seen.before);
      expect(add.mock.calls.some((c) => (c[0] as { owner?: string }).owner === 'site')).toBe(false);
      if (mode === 'on') {
        // Reconciling the app that is still up regenerates the file from what the router holds:
        // the refused app is the only block that goes.
        await eventually(async () => !(await readCaddyfile()).includes('site.localhost'));
        expect(await readCaddyfile()).toContain('blog.localhost');
      }
    }, 40000);

    it('deletes an ORPHAN instance (no state, no config) of a suspended name, both slots, and never DROP itself', async () => {
      await deployTwoAndStop();
      fakeRuntime.seedRunning('ghost', 47901);
      fakeRuntime.seedRunning('ghost.b', 47902);
      fakeRuntime.seedRunning('drop-platform', 47903);
      fakeRuntime.seedRunning('Ghost', 47904);
      await writeRecords(['ghost', 'drop-platform']);
      const heldAtStart = watchCaddyStart();
      platform = makePlatform({ bootReconcileMode: mode });
      const warn = jest.spyOn(internals().logger, 'warn');

      await platform.start();

      // Exact names only: `Ghost` is another name, and `drop-platform` is the platform's own process.
      expect(heldAtStart).toEqual([['Ghost', 'blog', 'drop-platform', 'site']]);
      expect(fakeRuntime.runningNames().sort()).toEqual(['Ghost', 'blog', 'drop-platform', 'site']);
      expect(warn.mock.calls.some((c) => String(c[0]).includes("'ghost'"))).toBe(true);
    }, 40000);
  });

  describe('boot enforcement: what it must not do', () => {
    it('an unreadable store deletes nothing and withdraws no route', async () => {
      await deployTwoAndStop();
      await fs.mkdir(path.dirname(suspensionsFile), { recursive: true });
      await fs.writeFile(suspensionsFile, '{ broken');
      jest.spyOn(console, 'error').mockImplementation();
      const heldAtStart = watchCaddyStart();
      const del = jest.spyOn(fakeRuntime, 'delete');
      const remove = jest.spyOn(RouterService.prototype, 'removeRoutesForApp');
      platform = makePlatform();
      const seen = watchEnforcement(platform);

      await platform.start();

      expect(getSuspensionStore().isCorrupt()).toBe(true);
      expect(heldAtStart).toEqual([['blog', 'site']]);
      expect(del).not.toHaveBeenCalled();
      expect(remove).not.toHaveBeenCalled();
      expect(getStateManager().getApp('site')?.status).toBe('running');
      expect(seen.before).toBeDefined();
      expect(seen.after).toBe(seen.before);
    }, 40000);

    it('revokes the minted key once more after the API has loaded the credentials', async () => {
      await deployTwoAndStop();
      await writeRecords(['site']);
      watchCaddyStart();
      const order: string[] = [];
      (createApiServer as jest.Mock).mockImplementationOnce(() => ({
        initialize: jest.fn().mockResolvedValue(undefined),
        start: jest.fn().mockImplementation(async () => {
          order.push('api-start');
        }),
        stop: jest.fn().mockResolvedValue(undefined),
      }));
      jest.spyOn(authModule, 'deleteApiKeysByName').mockImplementation(async (name: string) => {
        if (name.startsWith('app:')) order.push(`revoke ${name}`);
        return true;
      });
      platform = makePlatform({ enableApi: true });

      await platform.start();

      // Once before the API (a no-op in real life: no credentials yet), once after.
      expect(order).toEqual(['revoke app:site:provision', 'api-start', 'revoke app:site:provision']);
    }, 40000);

    it('a record that no known app matches changes nothing about the apps that are up', async () => {
      await deployTwoAndStop();
      await writeRecords(['nobody']);
      const heldAtStart = watchCaddyStart();
      platform = makePlatform();

      await platform.start();

      expect(heldAtStart).toEqual([['blog', 'site']]);
    }, 40000);

    it('a legacy keyless record resolves to the one app that matches ignoring case, and is enforced', async () => {
      platform = makePlatform();
      await platform.start();
      await deploy('MySite');
      await deploy('blog');
      await platform.stop();
      platform = null;
      expect(fakeRuntime.runningNames().sort()).toEqual(['MySite', 'blog']);
      await writeRecords(['mysite'], true);
      const heldAtStart = watchCaddyStart();
      platform = makePlatform();

      await platform.start();

      expect(heldAtStart).toEqual([['blog']]);
    }, 40000);
  });
});
